function IsValid(s: string) -> bool {
  let stack: string[] = [];
  let chars = s.chars();
  let n = chars.length();
  let i = 0;
  while (i < n) {
    let c = chars[i];
    if (c == "(" || c == "[" || c == "{") {
      stack.push(c);
    } else {
      let top = stack.pop();
      if (top == null) {
        return false;
      }
      if (c == ")" && top != "(") {
        return false;
      }
      if (c == "]" && top != "[") {
        return false;
      }
      if (c == "}" && top != "{") {
        return false;
      }
    }
    i += 1;
  }
  return stack.length() == 0;
}
